import { filmTextStyles } from '@/lib/filmSpecialTitles';
import { useEffect, useState, useRef, type MutableRefObject, type ReactNode } from 'react';
import { AlignCenter, AlignJustify, AlignLeft, AlignRight, Bold, Italic, Underline, List, ListOrdered, Undo2, Redo2, RemoveFormatting, Table2, MessageSquareText } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from './ui/popover';

type Props = { editor: MutableRefObject<HTMLDivElement | null>; command: (name:string,value?:string)=>void; captureSelection:()=>void; example:()=>void; image:()=>void; context:string; sectionSettings?: ReactNode };
const control='inline-flex h-10 min-w-10 shrink-0 items-center justify-center gap-2 rounded-md px-2 text-sm transition-colors hover:bg-ink/10 focus-visible:outline focus-visible:outline-2 focus-visible:outline-accent disabled:opacity-35 disabled:cursor-not-allowed';
export default function FilmEditorToolbar({editor,command,captureSelection,example,context,sectionSettings}:Props) {
  const [active,setActive]=useState<Record<string,boolean>>({}),[enabled,setEnabled]=useState(false),[style,setStyle]=useState('p');
  const [table,setTable]=useState(false),[rows,setRows]=useState(3),[cols,setCols]=useState(3);
  const [styleOpen,setStyleOpen]=useState(false);
  const selectedHeading=useRef<HTMLElement|null>(null);
  const [keywordHeading,setKeywordHeading]=useState<HTMLElement|null>(null),[keywords,setKeywords]=useState(''),[keywordMessage,setKeywordMessage]=useState('');
  useEffect(()=>{
    function refresh(){const selection=getSelection();if(!editor.current?.isConnected){setEnabled(false);return;}if(!selection?.anchorNode || !editor.current.contains(selection.anchorNode))return;setEnabled(true);const anchor=selection.anchorNode.nodeType===Node.ELEMENT_NODE?selection.anchorNode as Element:selection.anchorNode.parentElement;const block=anchor?.closest('p,h1,h2,h3,h4,h5,div');setStyle(block?.getAttribute('data-film-style')==='cover'?'cover-title':block?.getAttribute('data-film-style')==='section'?'section-title':block&&block!==editor.current?block.tagName.toLowerCase():'p');selectedHeading.current=anchor?.closest<HTMLElement>('h1,h2,h3,h4,h5')??null;const align=anchor?getComputedStyle(anchor).textAlign:'left';setActive({...Object.fromEntries(['bold','italic','underline','insertUnorderedList','insertOrderedList'].map(cmd=>[cmd,document.queryCommandState(cmd)])),justifyLeft:['left','start'].includes(align),justifyCenter:align==='center',justifyRight:['right','end'].includes(align),justifyFull:align==='justify'});}
    document.addEventListener('selectionchange',refresh);document.addEventListener('input',refresh);
    return()=>{document.removeEventListener('selectionchange',refresh);document.removeEventListener('input',refresh);};
  },[editor]);
  function tool(label:string,icon:ReactNode,cmd:string,shortcut?:string){return <button type="button" className={`${control} ${active[cmd]?'bg-accent/15 text-accent ring-1 ring-inset ring-accent/40':''}`} title={`${label}${shortcut?` (${shortcut})`:''}`} aria-label={label} aria-pressed={['undo','redo','removeFormat'].includes(cmd)?undefined:!!active[cmd]} disabled={!enabled} onClick={()=>command(cmd)}>{icon}</button>;}
  return <div data-film-toolbar className="sticky top-16 z-30 mb-5 rounded-lg border border-ink/25 bg-paper/95 shadow-lg backdrop-blur" onPointerDownCapture={captureSelection} onMouseDown={e=>{if((e.target as HTMLElement).closest('button'))e.preventDefault();}}>
    <div role="toolbar" aria-label="Mise en forme du film" className="flex flex-nowrap items-center gap-2 overflow-x-auto overscroll-x-contain whitespace-nowrap p-2 sm:flex-wrap sm:overflow-x-visible sm:whitespace-normal">
      {sectionSettings && <div role="group" aria-label="Paramètres de la section" className="shrink-0 border-r border-ink/15 pr-2">{sectionSettings}</div>}
      <div role="group" aria-label="Historique" className="flex shrink-0 border-r border-ink/15 pr-2">{tool('Annuler',<Undo2 size={18}/>,'undo','Ctrl+Z')}{tool('Rétablir',<Redo2 size={18}/>,'redo','Ctrl+Y')}</div>
      <Popover open={styleOpen} onOpenChange={setStyleOpen}><PopoverTrigger asChild><button id="film-text-style" type="button" role="combobox" aria-label="Style du texte" aria-expanded={styleOpen} aria-haspopup="listbox" aria-controls="film-style-options" className="flex h-10 w-44 shrink-0 items-center justify-between rounded-md border border-ink/20 bg-paper px-3 text-sm" disabled={!enabled} onKeyDownCapture={captureSelection}><span>{filmTextStyles.find(item=>item.value===style)?.label??'Texte normal'}</span><span aria-hidden>▾</span></button></PopoverTrigger><PopoverContent align="start" className="w-56 bg-paper p-1" onCloseAutoFocus={e=>e.preventDefault()}><div id="film-style-options" role="listbox" aria-label="Styles du texte" onKeyDown={e=>{const options=Array.from(e.currentTarget.querySelectorAll<HTMLButtonElement>('[role=option]'));const index=options.indexOf(document.activeElement as HTMLButtonElement);const next=e.key==='ArrowDown'?Math.min(options.length-1,index+1):e.key==='ArrowUp'?Math.max(0,index-1):e.key==='Home'?0:e.key==='End'?options.length-1:-1;if(next>=0){e.preventDefault();options[next].focus();}}}>{filmTextStyles.map(({value,label})=><button key={value} type="button" role="option" aria-selected={style===value||(value==='p'&&style==='div')} className="flex min-h-10 w-full items-center justify-between rounded px-3 text-left text-sm hover:bg-ink/10 focus:bg-ink/10 focus:outline-none" onMouseDown={e=>e.preventDefault()} onClick={()=>{command('formatBlock',value);setStyle(value);setStyleOpen(false);}}><span>{label}</span>{style===value&&<span aria-hidden>✓</span>}</button>)}</div></PopoverContent></Popover>
      <button type="button" className={control} disabled={!enabled} onClick={()=>{const node=getSelection()?.anchorNode;const element=node?.nodeType===Node.ELEMENT_NODE?node as Element:node?.parentElement;const heading=element?.closest<HTMLElement>('h1,h2,h3,h4,h5')??selectedHeading.current;if(!heading||!editor.current?.contains(heading)){setKeywordMessage('Placez le curseur dans un titre pour lui associer des mots-clés.');return;}setKeywordMessage('');setKeywordHeading(heading);setKeywords((JSON.parse(heading.getAttribute('data-index-keywords')||'[]') as string[]).join(', '));}}>Mots-clés du titre</button>
      <div role="group" aria-label="Caractères" className="flex shrink-0 border-r border-ink/15 pr-2">{tool('Gras',<Bold size={18}/>,'bold','Ctrl+B')}{tool('Italique',<Italic size={18}/>,'italic','Ctrl+I')}{tool('Souligné',<Underline size={18}/>,'underline','Ctrl+U')}{tool('Effacer la mise en forme',<RemoveFormatting size={18}/>,'removeFormat')}</div>
      <div role="group" aria-label="Alignement" className="flex shrink-0 border-r border-ink/15 pr-2">{tool('Aligner à gauche',<AlignLeft size={18}/>,'justifyLeft')}{tool('Centrer',<AlignCenter size={18}/>,'justifyCenter')}{tool('Aligner à droite',<AlignRight size={18}/>,'justifyRight')}{tool('Justifier',<AlignJustify size={18}/>,'justifyFull')}</div>
      <div role="group" aria-label="Listes" className="flex shrink-0 border-r border-ink/15 pr-2">{tool('Liste à puces',<List size={18}/>,'insertUnorderedList')}{tool('Liste numérotée',<ListOrdered size={18}/>,'insertOrderedList')}</div>
      <div role="group" aria-label="Insertion" className="flex shrink-0 gap-1"><button type="button" className={control} aria-label="Tableau" aria-expanded={table} disabled={!enabled} onClick={()=>setTable(!table)}><Table2 size={18}/><span>Tableau</span></button><button type="button" className={control} onClick={example}><MessageSquareText size={18}/><span>Encart gris</span></button></div>
    </div>
    <div className="flex min-h-8 items-center justify-between gap-3 border-t border-ink/10 px-3 py-1 text-xs text-muted-foreground"><span className="truncate">{enabled?context:'Cliquez dans le texte d’une page pour commencer'}</span><span className="hidden shrink-0 sm:inline">Ctrl+B · Ctrl+I · Ctrl+U · Ctrl+Z</span></div>
    {keywordMessage&&<p role="status" className="px-3 pb-2 text-sm">{keywordMessage}</p>}
    {keywordHeading&&<form role="dialog" aria-label="Mots-clés du titre" className="absolute inset-x-2 top-full mt-2 rounded-lg border bg-paper p-4 shadow-xl sm:left-auto sm:w-96" onSubmit={e=>{e.preventDefault();if(keywordHeading.isConnected){keywordHeading.setAttribute('data-index-keywords',JSON.stringify([...new Set(keywords.split(/[,;\n]/).map(w=>w.trim()).filter(Boolean))].slice(0,30)));editor.current?.focus({preventScroll:true});editor.current?.dispatchEvent(new Event('input',{bubbles:true}));}setKeywordHeading(null);}}><p className="mb-2 truncate font-semibold">{keywordHeading.textContent}</p><label className="text-sm">Mots-clés pour l’index<textarea autoFocus value={keywords} onChange={e=>setKeywords(e.target.value)} className="mt-2 w-full rounded border bg-paper p-2" placeholder="Ex. : enquête, indices, poursuite"/></label><p className="mb-3 text-xs text-muted-foreground">Séparez les mots-clés par des virgules. Ils apparaîtront dans l’index avec le numéro de cette page.</p><div className="flex gap-2"><button type="submit" className={`${control} bg-accent text-white`}>Enregistrer les mots-clés</button><button type="button" className={control} onClick={()=>setKeywordHeading(null)}>Fermer</button></div></form>}
    {table&&<form role="dialog" aria-label="Insérer un tableau" className="absolute inset-x-0 top-full mx-2 mt-2 flex flex-wrap items-end gap-3 rounded-lg border border-ink/25 bg-paper p-4 shadow-xl sm:inset-x-auto sm:right-0" onKeyDown={e=>{if(e.key==='Escape')setTable(false);}} onSubmit={e=>{e.preventDefault();if(!Number.isInteger(rows)||!Number.isInteger(cols)||rows<1||rows>20||cols<1||cols>8)return;command('insertHTML',`<table><tbody>${Array.from({length:rows},(_,r)=>`<tr>${Array.from({length:cols},()=>r?'<td>Texte</td>':'<th>Titre</th>').join('')}</tr>`).join('')}</tbody></table><p><br></p>`);setTable(false);}}><label className="text-sm">Lignes<input autoFocus type="number" min={1} max={20} required value={rows} onChange={e=>setRows(Number(e.target.value))} className="mt-1 block h-10 w-20 rounded border border-ink/25 bg-paper px-2"/></label><label className="text-sm">Colonnes<input type="number" min={1} max={8} required value={cols} onChange={e=>setCols(Number(e.target.value))} className="mt-1 block h-10 w-20 rounded border border-ink/25 bg-paper px-2"/></label><button type="submit" className={`${control} bg-accent text-white`}>Insérer le tableau</button><button type="button" className={control} onClick={()=>setTable(false)}>Fermer</button></form>}
  </div>;
}
